/* ---------- batch six ---------- */
.bt{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:38px;padding:0 16px;font-family:var(--sans);font-size:13.5px;font-weight:600;border:1px solid transparent;white-space:nowrap;transition:background-color .2s ease,border-color .2s ease,color .2s ease,transform .15s ease,box-shadow .2s ease,opacity .2s ease}
.bt:active:not(:disabled){transform:scale(.97)}
.bt:focus-visible{outline:none;box-shadow:0 0 0 3px var(--accent-bg);border-color:var(--accent)}
.bt-primary{background:var(--accent-hi);color:#120a02}
.bt-primary:hover:not(:disabled){background:var(--accent)}
.bt-secondary{background:var(--panel);border-color:var(--icon-line);color:var(--text)}
.bt-secondary:hover:not(:disabled){border-color:var(--text-dim)}
.bt-ghost{background:transparent;color:var(--text)}
.bt-ghost:hover:not(:disabled){background:var(--chip)}
.bt-danger{background:rgba(255,90,95,.08);border-color:rgba(255,90,95,.3);color:var(--danger)}
.bt-danger:hover:not(:disabled){background:rgba(255,90,95,.14)}
.bt-sm{height:30px;padding:0 11px;font-size:12.5px;gap:6px}
.bt-lg{height:46px;padding:0 22px;font-size:15px}
.bt-icon{width:38px;padding:0}
.bt:disabled{opacity:.45;cursor:not-allowed}
.bt.ok{background:var(--success);color:#fff;border-color:var(--success)}
.bt-spin{display:inline-block;width:14px;height:14px;flex:none;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .8s linear infinite}
.bt-ic{display:inline-grid;place-items:center;width:16px;height:16px}

/* comments */
.dz{max-width:440px}
.dz-head{display:flex;align-items:center;justify-content:space-between;padding:14px 16px}
.dz-head .t{font-weight:600;font-size:15px}
.dz-comp{position:relative;margin:0 16px 4px;border:1px solid var(--icon-line);background:var(--panel);transition:border-color .2s,box-shadow .2s}
.dz-comp.focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.dz-ed{min-height:46px;padding:12px 12px 4px;font-size:14px;line-height:1.5;outline:none;color:var(--text)}
.dz-ed:empty::before{content:attr(data-ph);color:var(--muted)}
.dz-men{display:inline-block;padding:0 6px;color:var(--accent);background:var(--accent-bg);font-weight:500}
.dz-tools{display:flex;align-items:center;justify-content:flex-end;gap:8px;padding:6px 8px 8px}
.dz-tools .ib{width:30px;height:30px}
.dz-menu{position:absolute;left:10px;top:44px;z-index:5;width:240px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 14px 32px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px);transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.dz-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.dz-mi{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;font-size:13.5px;font-weight:500;color:var(--text);transition:background-color .15s}
.dz-mi.act{background:var(--chip)}
.dz-av{position:relative;width:28px;height:28px;flex:none}
.dz-av img{width:100%;height:100%;border-radius:50%;display:block}
.dz-av i{position:absolute;right:-1px;bottom:-1px;width:9px;height:9px;border-radius:50%;background:var(--muted);box-shadow:0 0 0 2px var(--panel)}
.dz-av i.on{background:#22c55e}
.dz-list{padding:6px 0 4px}
.dz-c{padding:14px 16px;border-top:1px solid var(--line)}
.dz-c:first-child{border-top:0}
.dz-top{display:flex;align-items:center;gap:10px}
.dz-top .dz-av{width:32px;height:32px}
.dz-n{font-size:14px;font-weight:600}
.dz-role{font-size:11.5px;color:var(--muted)}
.dz-time{margin-left:auto;font-size:12px;color:var(--muted)}
.dz-body{margin:8px 0 10px 42px;font-size:14px;line-height:1.55;color:var(--text-dim)}
.dz-acts{display:flex;align-items:center;gap:6px;margin-left:42px}
.dz-r{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 9px;border:1px solid var(--line);font-size:12.5px;font-weight:600;color:var(--text-dim);transition:border-color .2s,background-color .2s,color .2s,transform .15s}
.dz-r:active{transform:scale(.94)}
.dz-r.on{border-color:var(--accent-icon-line);background:var(--accent-bg);color:var(--text)}
.dz-reply{margin-left:6px;font-size:12.5px;font-weight:500;color:var(--text-dim)}
.dz-reply:hover{color:var(--text)}

/* ---------- comments ---------- */
{
  const ed = $('#dz-ed'), menu = $('#dz-menu'), list = $('#dz-list'), send = $('#dz-send'), comp = $('#dz-comp');
  const people = [['Joanna Kim', true], ['Jonas Weber', false], ['Maya Chen', true], ['Oscar Lind', false], ['Priya Nair', true]];
  let comments = [
    { who:'Maya Chen', on:true, role:'Design lead', t:'2h', ts:2, body:'The new pricing cards read much better. Could we try the annual toggle above the cards so it is the first thing people see?', r:[['👍', 4, false], ['🎉', 2, false]] },
    { who:'Oscar Lind', on:false, role:'Engineer', t:'5h', ts:5, body:'Tokens are wired up on staging. The card padding now follows the spacing scale, so the mobile layout lines up.', r:[['👀', 1, false], ['👍', 6, false]] },
    { who:'Priya Nair', on:true, role:'PM', t:'1d', ts:24, body:'Shared this with the sales team for feedback before Thursday.', r:[['🙌', 3, false]] }
  ];
  let order = 'new', mIdx = 0, matches = [], open = false;
  const score = c => c.r.reduce((a, x) => a + x[1], 0);
  function render(){
    const sorted = comments.slice().sort((a, b) => order === 'new' ? a.ts - b.ts : score(b) - score(a));
    list.innerHTML = sorted.map(c => `<div class="dz-c" data-k="${comments.indexOf(c)}">
      <div class="dz-top">${avatar(c.who, c.on)}<div><div class="dz-n">${c.who}</div><span class="dz-role">${c.role}</span></div><span class="dz-time">${c.t}</span></div>
      <div class="dz-body">${c.body}</div>
      <div class="dz-acts">${c.r.map((r, i) => `<button class="dz-r ${r[2] ? 'on' : ''}" data-i="${i}">${r[0]} <span>${r[1]}</span></button>`).join('')}<button class="dz-reply">Reply</button></div>
    </div>`).join('');
  }
  list.addEventListener('click', e => {
    const r = e.target.closest('.dz-r'), c = e.target.closest('.dz-c'); if (!c) return;
    const cm = comments[+c.dataset.k];
    if (r){ const x = cm.r[+r.dataset.i]; x[2] = !x[2]; x[1] += x[2] ? 1 : -1; r.classList.toggle('on', x[2]); r.querySelector('span').textContent = x[1]; Sound.play(x[2] ? 'pop' : 'tick'); }
    else if (e.target.closest('.dz-reply')){ ed.focus(); insertMention(cm.who); }
  });
  function caretWord(){
    const s = getSelection(); if (!s.rangeCount) return null; const r = s.getRangeAt(0); const n = r.startContainer;
    if (n.nodeType !== 3) return null; const before = n.textContent.slice(0, r.startOffset); const m = before.match(/@(\w*)$/);
    return m ? { node:n, start:r.startOffset - m[0].length, end:r.startOffset, q:m[1] } : null;
  }
  function showMenu(q){
    matches = people.filter(p => p[0].toLowerCase().startsWith(q.toLowerCase()) || p[0].split(' ')[1].toLowerCase().startsWith(q.toLowerCase()));
    if (!matches.length){ hideMenu(); return; }
    mIdx = 0; open = true;
    menu.innerHTML = matches.map((p, i) => `<button class="dz-mi ${i === 0 ? 'act' : ''}" data-i="${i}">${avatar(p[0], p[1])}${p[0]}</button>`).join('');
    menu.classList.add('show');
  }
  function hideMenu(){ open = false; menu.classList.remove('show'); }
  function insertMention(name, w){
    const s = getSelection(); w = w || caretWord();
    const chip = document.createElement('span'); chip.className = 'dz-men'; chip.contentEditable = 'false'; chip.textContent = '@' + name;
    const space = document.createTextNode('\u00a0');
    if (w){ const range = document.createRange(); range.setStart(w.node, w.start); range.setEnd(w.node, w.end); range.deleteContents(); range.insertNode(space); range.insertNode(chip); }
    else { ed.appendChild(chip); ed.appendChild(space); }
    const r = document.createRange(); r.setStartAfter(space); r.collapse(true); s.removeAllRanges(); s.addRange(r);
    hideMenu(); update(); Sound.play('select');
  }
  function update(){ send.disabled = !ed.textContent.trim(); }
  ed.addEventListener('focus', () => comp.classList.add('focus'));
  ed.addEventListener('blur', () => { comp.classList.remove('focus'); setTimeout(hideMenu, 150); });
  ed.addEventListener('input', () => { update(); const w = caretWord(); if (w) showMenu(w.q); else hideMenu(); });
  ed.addEventListener('keydown', e => {
    if (open){
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); mIdx = (mIdx + (e.key === 'ArrowDown' ? 1 : -1) + matches.length) % matches.length; $$('.dz-mi', menu).forEach((b, i) => b.classList.toggle('act', i === mIdx)); Sound.play('tick'); return; }
      if (e.key === 'Enter' || e.key === 'Tab'){ e.preventDefault(); insertMention(matches[mIdx][0]); return; }
      if (e.key === 'Escape'){ hideMenu(); return; }
    }
    if (e.key === 'Enter' && !e.shiftKey){ e.preventDefault(); post(); }
  });
  menu.addEventListener('mousedown', e => { const b = e.target.closest('.dz-mi'); if (b){ e.preventDefault(); insertMention(matches[+b.dataset.i][0]); } });
  $('#dz-at').addEventListener('mousedown', e => {
    e.preventDefault(); ed.focus();
    const s = getSelection(); if (!s.rangeCount || !ed.contains(s.anchorNode)){ const r = document.createRange(); r.selectNodeContents(ed); r.collapse(false); s.removeAllRanges(); s.addRange(r); }
    document.execCommand('insertText', false, '@'); showMenu('');
  });
  function post(){
    if (!ed.textContent.trim()) return;
    const html = Array.from(ed.childNodes).map(n => n.nodeType === 3 ? esc(n.textContent) : (n.classList && n.classList.contains('dz-men') ? `<span class="dz-men">${esc(n.textContent)}</span>` : esc(n.textContent))).join('');
    comments.forEach(c => c.ts += 0.01);
    comments.push({ who:'Sam Rivera', on:true, role:'You', t:'now', ts:0, body:html, r:[] });
    ed.innerHTML = ''; update(); Sound.play('send');
    if (order !== 'new'){ order = 'new'; $$('#dz-seg button').forEach(b => b.classList.toggle('on', b.dataset.v === 'new')); dispatchEvent(new Event('resize')); }
    render(); const first = $('.dz-c', list); if (first) first.classList.add('enter');
  }
  send.addEventListener('click', post);
  segInit($('#dz-seg'), v => { order = v; flip(() => $$('.dz-c', list), () => {
    const els = new Map($$('.dz-c', list).map(el => [+el.dataset.k, el]));
    comments.slice().sort((a, b) => v === 'new' ? a.ts - b.ts : score(b) - score(a)).forEach(c => list.appendChild(els.get(comments.indexOf(c))));
  }); });
  render();
}
